mapper.select:
SELECT *
FROM t_cs_ticket


        AND INSTR(ticket_no, #{query.ticketNo})


        AND INSTR(title, #{query.title})


        AND ticket_type = #{query.ticketType}


        AND priority = #{query.priority}


        AND status = #{query.status}


        AND create_time >= #{query.createTimeBegin}


        AND create_time < DATE_ADD(#{query.createTimeEnd}, INTERVAL 1 DAY)


        AND deleted_flag = #{query.deletedFlag}



    ORDER BY ticket_id DESC
